package dev.supplychain.agent.planning.api;

/** Request-level complexity estimate supplied by trusted application code, not generated by a planner. */
public record PlanningComplexity(int expectedBranchingFactor, int expectedHorizon,
                                 double uncertainty, double consequenceSeverity) {
    public PlanningComplexity {
        if (expectedBranchingFactor < 0 || expectedHorizon < 0) throw new IllegalArgumentException("branching and horizon cannot be negative");
        if (!Double.isFinite(uncertainty) || uncertainty < 0 || uncertainty > 1
                || !Double.isFinite(consequenceSeverity) || consequenceSeverity < 0 || consequenceSeverity > 1) {
            throw new IllegalArgumentException("uncertainty and consequenceSeverity must be in [0,1]");
        }
    }
}
